#!/usr/bin/env node
// Bundle composition report (PRD agent-first-authoring, WP-C1; PRD beat-threejs-3, companion Track C).
//
//   node tools/bundle-report/report.mjs <dist-dir> [--name <label>] [--json <out.json>] [--md <out.md>]
//
// Reads a Vite build built with `build.sourcemap: true`. For every emitted JS chunk it reports raw and gzip bytes, and
// attributes each generated byte to the source file the sourcemap maps it to, rolled up to an npm package
// (`@aura3d/engine`, `@aura3d/rendering`, ...) or `app` for the project's own code. Bytes no mapping covers are
// `(unmapped)`. Pure Node, no dependencies.
import { readFileSync, readdirSync, statSync, writeFileSync, existsSync } from "node:fs";
import { gzipSync } from "node:zlib";
import { join, relative, basename } from "node:path";

const B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
const B64_INDEX = new Map([...B64].map((c, i) => [c, i]));

/** Decode one sourcemap `mappings` line into [generatedColumn, sourceIndex | -1] segments. */
export function decodeMappings(mappings) {
  const lines = [];
  let source = 0;
  for (const line of mappings.split(";")) {
    const segs = [];
    let col = 0;
    for (const seg of line.split(",")) {
      if (!seg) continue;
      const values = [];
      let value = 0, shift = 0;
      for (const ch of seg) {
        const digit = B64_INDEX.get(ch);
        if (digit === undefined) throw new Error(`bad base64 VLQ digit "${ch}"`);
        value += (digit & 31) << shift;
        if (digit & 32) { shift += 5; continue; }
        values.push(value & 1 ? -(value >>> 1) : value >>> 1);
        value = 0; shift = 0;
      }
      col += values[0];
      if (values.length >= 4) { source += values[1]; segs.push([col, source]); } else segs.push([col, -1]);
      // values[2], values[3] (original line and column) and values[4] (name) are not needed for attribution.
    }
    lines.push(segs);
  }
  return lines;
}

/** Map a sourcemap source path to the npm package (or "app") that owns it. */
export function packageOf(source) {
  return areaOf(source).split(" > ")[0];
}

/**
 * Finer owner: the package plus the first folders of its published `dist/` (two levels under `dist/engine` and
 * `dist/rendering`), e.g. "@aura3d/engine > rendering/forward". Published Aura3D packages ship one dist tree with no
 * chained sourcemaps, so this is the finest attribution a consumer build allows.
 */
export function areaOf(source) {
  const s = source.replace(/\\/g, "/");
  const nm = s.lastIndexOf("node_modules/");
  if (nm >= 0) {
    const rest = s.slice(nm + "node_modules/".length).split("/");
    const scoped = rest[0].startsWith("@");
    const pkg = scoped ? `${rest[0]}/${rest[1]}` : rest[0];
    const inner = rest.slice(scoped ? 2 : 1);
    if (inner[0] !== "dist" || inner.length < 3) return pkg;
    const depth = ["engine", "rendering"].includes(inner[1]) && inner.length > 3 ? 2 : 1;
    return `${pkg} > ${inner.slice(1, 1 + depth).join("/")}`;
  }
  if (/^\0|^\x00|vite\/|commonjsHelpers|preload-helper|modulepreload/.test(s)) return "(vite runtime)";
  return "app";
}

/** Attribute every byte of `code` to a package using its sourcemap. Returns { [package]: bytes }. */
export function attribute(code, map) {
  const out = new Map();
  const add = (k, n) => { if (n > 0) out.set(k, (out.get(k) ?? 0) + n); };
  const sources = (map.sources ?? []).map((src) => areaOf(src));
  const decoded = decodeMappings(map.mappings ?? "");
  const lines = code.split("\n");
  for (let i = 0; i < lines.length; i++) {
    const len = lines[i].length + (i < lines.length - 1 ? 1 : 0);
    const segs = decoded[i] ?? [];
    if (segs.length === 0) { add("(unmapped)", len); continue; }
    if (segs[0][0] > 0) add("(unmapped)", segs[0][0]);
    for (let k = 0; k < segs.length; k++) {
      const [col, src] = segs[k];
      const end = k + 1 < segs.length ? segs[k + 1][0] : len;
      add(src >= 0 ? sources[src] ?? "(unmapped)" : "(unmapped)", Math.max(0, end - col));
    }
  }
  return Object.fromEntries([...out].sort((a, b) => b[1] - a[1]));
}

function walk(dir, out = []) {
  for (const name of readdirSync(dir)) {
    const p = join(dir, name);
    if (statSync(p).isDirectory()) walk(p, out); else out.push(p);
  }
  return out;
}

/** Report for a dist directory: chunks with raw/gzip bytes and per-package attribution, plus totals. */
export function reportDist(dist, name = basename(dist)) {
  const files = walk(dist);
  const js = files.filter((f) => /\.m?js$/.test(f)).sort();
  const chunks = [];
  const packages = new Map();
  const areas = new Map();
  for (const file of js) {
    const code = readFileSync(file, "utf8");
    const raw = Buffer.byteLength(code);
    const gzip = gzipSync(code, { level: 9 }).length;
    const mapFile = `${file}.map`;
    const byPackage = existsSync(mapFile) ? attribute(code, JSON.parse(readFileSync(mapFile, "utf8"))) : { "(no sourcemap)": raw };
    for (const [k, v] of Object.entries(byPackage)) {
      areas.set(k, (areas.get(k) ?? 0) + v);
      const pkg = k.split(" > ")[0];
      packages.set(pkg, (packages.get(pkg) ?? 0) + v);
    }
    chunks.push({ file: relative(dist, file), raw, gzip, byArea: byPackage });
  }
  const other = files.filter((f) => !/\.m?js(\.map)?$/.test(f)).map((f) => ({ file: relative(dist, f), raw: statSync(f).size }));
  const totalRaw = chunks.reduce((s, c) => s + c.raw, 0);
  const totalGzip = chunks.reduce((s, c) => s + c.gzip, 0);
  return { name, jsFiles: chunks.length, totalRaw, totalGzip, packages: Object.fromEntries([...packages].sort((a, b) => b[1] - a[1])), areas: Object.fromEntries([...areas].sort((a, b) => b[1] - a[1])), chunks: chunks.sort((a, b) => b.raw - a.raw), otherFiles: other.sort((a, b) => b.raw - a.raw) };
}

const kb = (n) => `${(n / 1024).toFixed(1)} KB`;
export function toMarkdown(r) {
  const lines = [`### ${r.name}`, "", `${r.jsFiles} JS files, ${kb(r.totalRaw)} raw, ${kb(r.totalGzip)} gzip (sum of per-file gzip -9).`, "", "| Package | Raw bytes in JS | Share |", "| --- | ---: | ---: |"];
  for (const [k, v] of Object.entries(r.packages)) lines.push(`| ${k} | ${kb(v)} | ${((100 * v) / r.totalRaw).toFixed(1)}% |`);
  lines.push("", "| Area (package > dist folder) | Raw bytes in JS | Share |", "| --- | ---: | ---: |");
  for (const [k, v] of Object.entries(r.areas).slice(0, 25)) lines.push(`| ${k} | ${kb(v)} | ${((100 * v) / r.totalRaw).toFixed(1)}% |`);
  lines.push("", "| Chunk | Raw | Gzip | Largest contributors |", "| --- | ---: | ---: | --- |");
  for (const c of r.chunks.slice(0, 15)) {
    const top = Object.entries(c.byArea).slice(0, 3).map(([k, v]) => `${k} ${kb(v)}`).join(", ");
    lines.push(`| ${c.file} | ${kb(c.raw)} | ${kb(c.gzip)} | ${top} |`);
  }
  if (r.chunks.length > 15) lines.push(`| (${r.chunks.length - 15} more) | ${kb(r.chunks.slice(15).reduce((s, c) => s + c.raw, 0))} | ${kb(r.chunks.slice(15).reduce((s, c) => s + c.gzip, 0))} | |`);
  const big = r.otherFiles.filter((f) => f.raw > 50 * 1024);
  if (big.length) { lines.push("", "Non-JS files over 50 KB: " + big.map((f) => `${f.file} ${kb(f.raw)}`).join(", ") + "."); }
  return lines.join("\n");
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const args = process.argv.slice(2);
  const opt = (n) => { const i = args.indexOf(n); return i >= 0 ? args[i + 1] : undefined; };
  const dist = args.find((a, i) => !a.startsWith("--") && !["--name", "--json", "--md"].includes(args[i - 1]));
  if (!dist) { console.error("usage: node tools/bundle-report/report.mjs <dist-dir> [--name label] [--json out.json] [--md out.md]"); process.exit(2); }
  const r = reportDist(dist, opt("--name"));
  if (opt("--json")) writeFileSync(opt("--json"), JSON.stringify(r, null, 2) + "\n");
  const md = toMarkdown(r);
  if (opt("--md")) writeFileSync(opt("--md"), md + "\n");
  console.log(md);
}
